(\lambda y^\mu.t)[x:=s]=
\begin{cases}
\lambda y^\mu.t, & \mu=\sigma\land y=x,\\
\lambda y^\mu.(t[x:=s]), & y\notin\operatorname{FV}_{494}(s)\land(\mu\ne\sigma\lor y\ne x),\\
\lambda z^\mu.\bigl((t[y:=z])[x:=s]\bigr), & y\in\operatorname{FV}_{494}(s)\land(\mu\ne\sigma\lor y\ne x),
\end{cases}

(Q_\mu y\,P)[x:=s]=
\begin{cases}
Q_\mu y\,P, & \mu=\sigma\land y=x,\\
Q_\mu y\,(P[x:=s]), & y\notin\operatorname{FV}_{494}(s)\land(\mu\ne\sigma\lor y\ne x),\\
Q_\mu z\,\bigl((P[y:=z])[x:=s]\bigr), & y\in\operatorname{FV}_{494}(s)\land(\mu\ne\sigma\lor y\ne x),
\end{cases}
